// "Make one" (/make/): a prompt in, a drop-in snippet out, all in this browser. The prompt is
// matched against the recipe table (make.mjs + table.json, generated by the engine: the same matcher
// fe anim runs), the snippet is that scene's prebuilt template (templates/<variant>.json) filled with
// the matched data, and its gzip size is measured here (CompressionStream) into its own header.
// Nothing is sent anywhere: no server, no tracking; words no recipe knows are shown, logged nowhere.
/* global FIZLET_VERSION */
import { makeSnippet, matchPrompt, variantOf } from "./make.mjs";
import TABLE from "./table.json";
import { matchedHtml, missHtml, recipeText } from "./render.mjs";

const $ = (sel) => document.querySelector(sel);
const form = $("[data-make]"), input = $("#make-prompt"), out = $("[data-out]"), stage = $("[data-stage]");
const code = $("[data-code]"), size = $("[data-snippet-size]"), dl = $("[data-download]"), copy = $("[data-copy-snippet]");
const recipeEl = $("[data-recipe]"), matchedEl = $("[data-matched]"), missEl = $("[data-miss]"), status = $("[data-status]");
const templates = new Map();
const base = new URL("./", import.meta.url);

const gzipSize = async (text) => (await new Response(new Blob([text]).stream().pipeThrough(new CompressionStream("gzip"))).arrayBuffer()).byteLength;
const template = (v) => {
  if (!templates.has(v)) templates.set(v, fetch(new URL(`templates/${v}.json`, base)).then((r) => (r.ok ? r.json() : Promise.reject(new Error(`templates/${v}.json: ${r.status}`)))).then((t) => t.code));
  return templates.get(v);
};

/** The preview: the snippet alone in a sandboxed frame, on this page's surface tokens. */
function preview(text) {
  const css = getComputedStyle(document.documentElement);
  const v = (name) => css.getPropertyValue(name).trim();
  const frame = document.createElement("iframe");
  frame.title = "Live preview of the snippet";
  frame.setAttribute("sandbox", "allow-scripts");
  frame.srcdoc = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Preview</title>` +
    `<style>body{margin:0;padding:12px;background:${v("--surface")};color:${v("--ink")};font:16px/1.5 system-ui,sans-serif}a{color:${v("--k-sys")}}h2,h3{margin:.3em 0}</style></head><body>${text}</body></html>`;
  stage.replaceChildren(frame);
}

let url = null, run = 0;
async function make(prompt) {
  const id = ++run;
  let spec;
  try {
    spec = matchPrompt(TABLE, prompt);
  } catch {
    status.textContent = "Type at least three letters.";
    return;
  }
  status.textContent = "Making it…";
  const made = await makeSnippet(TABLE, spec, await template(variantOf(TABLE, spec)), { version: FIZLET_VERSION, gzipSize });
  if (id !== run) return;
  recipeEl.textContent = recipeText(spec);
  matchedEl.innerHTML = matchedHtml(spec);
  missEl.innerHTML = missHtml(spec);
  size.innerHTML = `<b>${made.size.toLocaleString("en-US")} B</b><small>gzip · the whole snippet</small>`;
  code.value = made.text;
  if (url) URL.revokeObjectURL(url);
  url = URL.createObjectURL(new Blob([made.text], { type: "text/html" }));
  dl.href = url;
  dl.download = `fizlet-${spec.id}.html`;
  out.dataset.id = spec.id;
  preview(made.text);
  status.textContent = `Made “${spec.title}”: ${made.size.toLocaleString("en-US")} B gzip.`;
  const q = new URL(location.href);
  q.searchParams.set("p", prompt);
  history.replaceState(null, "", q);
}

form.addEventListener("submit", (ev) => {
  ev.preventDefault();
  void make(input.value);
});
for (const key of document.querySelectorAll("[data-try]"))
  key.addEventListener("click", () => {
    input.value = key.dataset.try;
    void make(input.value);
  });
copy.addEventListener("click", async () => {
  const label = copy.lastChild;
  try {
    await navigator.clipboard.writeText(code.value);
    label.nodeValue = "Copied";
  } catch {
    code.select();
    label.nodeValue = "Selected: copy it";
  }
  setTimeout(() => (label.nodeValue = "Copy snippet"), 1400);
});
const asked = new URLSearchParams(location.search).get("p");
if (asked) input.value = asked.slice(0, 200);
void make(input.value);
